#include <vector>
#include <cstddef>
#include <limits>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    size_t first = std::numeric_limits<size_t>::max();

    #pragma omp parallel for default(none) shared(x) reduction(min:first)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(x.size()); ++i) {
        if ((x[static_cast<size_t>(i)] & 1) == 0) {
            size_t idx = static_cast<size_t>(i);
            if (idx < first) {
                first = idx;
            }
        }
    }

    return first == std::numeric_limits<size_t>::max() ? x.size() : first;
}
